begin;
set local lock_timeout='5s';set local statement_timeout='60s';
do $$begin if not exists(select 1 from spot_private.privacy_environment where environment='staging')or(current_setting('supabase.project_ref',true)is not null and current_setting('supabase.project_ref',true)<>'zjinjtkekmaqtxsuyvho')then raise exception 'OPS_STAGING_ONLY';end if;end$$;
create table spot_private.ops_control(singleton boolean primary key default true check(singleton),enabled boolean not null default false,test_only boolean not null default true,purge_ready boolean not null default false,constraint ops_purge_readiness check(not enabled or test_only or purge_ready),email_enabled boolean not null default false check(not email_enabled),retention interval not null default interval '14 days' check(retention=interval '14 days'),dropped bigint not null default 0);
insert into spot_private.ops_control(singleton)values(true);
create table spot_private.ops_admission(request_id uuid primary key,created_at timestamptz not null default clock_timestamp());
create table spot_private.ops_events(id bigint generated always as identity primary key,request_id uuid not null,operation text not null,source text not null check(source in('client','edge','job')),result text not null check(result in('success','failure','expected_off','cancelled')),error_class text check(error_class in('validation_error','authorization_error','conflict_error','dependency_error','timeout_error','internal_error')),duration_ms integer not null check(duration_ms between 0 and 60000),created_at timestamptz not null default clock_timestamp(),unique(source,operation,request_id));
create index ops_events_recent on spot_private.ops_events(operation,source,created_at desc,id desc);
create index ops_events_source_time on spot_private.ops_events(source,created_at);
create index ops_events_expiry on spot_private.ops_events(created_at);
create table spot_private.ops_incidents(id uuid primary key default gen_random_uuid(),operation text not null,source text not null,rule text not null check(rule in('three_failures','error_spike','job_failure')),state text not null default 'open'check(state in('open','resolved')),opened_at timestamptz not null default clock_timestamp(),last_failure_at timestamptz not null default clock_timestamp(),last_success_at timestamptz,occurrences integer not null default 1,resolved_at timestamptz,email_state text not null default 'disabled_provider'check(email_state='disabled_provider'));
create unique index ops_open_incident on spot_private.ops_incidents(operation,source)where state='open';
create table spot_private.ops_jobs(operation text primary key,last_success_at timestamptz,last_failure_at timestamptz,failure_class text,last_duration_ms integer,consecutive_failures integer not null default 0,updated_at timestamptz not null default clock_timestamp());
do $$declare t text;begin foreach t in array array['ops_control','ops_admission','ops_events','ops_incidents','ops_jobs']loop execute format('alter table spot_private.%I enable row level security',t);execute format('revoke all on spot_private.%I from public,anon,authenticated,service_role',t);end loop;end$$;
create function spot_private.ops_operation_valid(value text)returns boolean language sql immutable set search_path=''as $$select value=any(array['auth.login','auth.callback','auth.bootstrap','photo.upload','photo.canonical','photo.save','photo.sign','photo.cleanup','dd.allocate','dd.read','tribe.spot','ora.start','ora.end','ora.read','ora.spot','spotted.post','spotted.comment','spotted.request','spotted.decide','spotted.share','match.create','chat.write','chat.read','notifications.subscribe','notifications.dispatch','notifications.prune','analytics.ingest','analytics.purge','moderation.report','moderation.action','moderation.audit','runtime.bootstrap','runtime.navigation','runtime.offline','privacy.retention','ops.purge'])$$;
create function spot_private.ops_expected_off(op text)returns boolean language sql stable security definer set search_path=''as $$select case when op like 'dd.%'or op='tribe.spot'then not(select discovery_enabled from spot_private.soma_v2_control)when op like 'notifications.%'then not(select enabled from spot_private.notification_control)when op like 'analytics.%'then not(select enabled from spot_private.analytics_control)when op in('photo.upload','photo.canonical','photo.save')then(select phase<>'OPEN'from spot_private.photo_cutover_control)when op like 'ora.%'then not(select ora_enabled from spot_private.soma_v2_control)when op='privacy.retention'then(select paused from spot_private.retention_control)when op='ops.purge'then not(select enabled from spot_private.ops_control)when op='photo.cleanup'then not(select execute_enabled from spot_private.photo_cutover_control)else false end$$;
create table spot_private.ops_job_policy(operation text primary key,expected_interval interval check(expected_interval>interval '0'));
insert into spot_private.ops_job_policy(operation)values('photo.cleanup'),('notifications.dispatch'),('notifications.prune'),('analytics.purge'),('privacy.retention'),('ops.purge');
update spot_private.ops_job_policy set expected_interval=interval '1 minute'where operation in('photo.cleanup','privacy.retention');
alter table spot_private.ops_job_policy enable row level security;revoke all on spot_private.ops_job_policy from public,anon,authenticated,service_role;
create function spot_private.ops_record(op text,rid uuid,outcome text,classification text,elapsed integer,origin text)returns boolean language plpgsql security definer set search_path=''as $$declare n int;fails int;streak int;rule_name text;stamp timestamptz:=clock_timestamp();is_job boolean:=origin='job';begin
 if not coalesce(spot_private.ops_operation_valid(op),false)or rid is null or outcome is null or outcome not in('success','failure','expected_off','cancelled')or origin is null or origin not in('client','edge','job')or elapsed is null or elapsed not between 0 and 60000 or classification is not null and classification not in('validation_error','authorization_error','conflict_error','dependency_error','timeout_error','internal_error')then raise exception 'OPS_INPUT'using errcode='22023';end if;
 if not exists(select 1 from spot_private.ops_control where enabled)then return false;end if;
 if exists(select 1 from spot_private.ops_control where test_only)and not exists(select 1 from spot_private.ops_admission where request_id=rid)then return false;end if;
 if spot_private.ops_expected_off(op)then outcome:='expected_off';classification:=null;end if;
 perform pg_advisory_xact_lock(hashtextextended('soma-operational-recorder',53));
 if(select count(*)from spot_private.ops_events where source=origin and created_at>stamp-interval '1 hour')>=(case when origin='client'then 1000 else 25000 end)then update spot_private.ops_control set dropped=dropped+1;return false;end if;
 insert into spot_private.ops_events(request_id,operation,source,result,error_class,duration_ms)values(rid,op,origin,outcome,case when outcome='failure'then coalesce(classification,'internal_error')end,elapsed)on conflict(source,operation,request_id)do nothing;if not found then return false;end if;
 -- Client telemetry is untrusted: it can never create or resolve a server incident.
 if origin='client'then return true;end if;
 if is_job and outcome in('success','failure')and op in('photo.cleanup','notifications.dispatch','notifications.prune','analytics.purge','privacy.retention','ops.purge')then
  insert into spot_private.ops_jobs(operation,last_success_at,last_failure_at,failure_class,last_duration_ms,consecutive_failures)values(op,case when outcome='success'then stamp end,case when outcome='failure'then stamp end,classification,elapsed,case when outcome='failure'then 1 else 0 end)
  on conflict(operation)do update set last_success_at=coalesce(excluded.last_success_at,ops_jobs.last_success_at),last_failure_at=coalesce(excluded.last_failure_at,ops_jobs.last_failure_at),failure_class=excluded.failure_class,last_duration_ms=elapsed,consecutive_failures=case when outcome='failure'then ops_jobs.consecutive_failures+1 else 0 end,updated_at=stamp;
 end if;
 if outcome='success'then update spot_private.ops_incidents set last_success_at=stamp where operation=op and source=origin and state='open';return true;end if;
 if outcome<>'failure'or classification in('validation_error','authorization_error','conflict_error')then return true;end if;
 select count(*),count(*)filter(where result='failure'and error_class in('dependency_error','timeout_error','internal_error'))into n,fails from spot_private.ops_events where operation=op and source=origin and created_at>stamp-interval '10 minutes'and result in('success','failure');
 select count(*)filter(where result='failure'and error_class in('dependency_error','timeout_error','internal_error'))into streak from(select result,error_class from spot_private.ops_events where operation=op and source=origin and created_at>stamp-interval '10 minutes'order by created_at desc,id desc limit 3)x;
 if is_job and(select consecutive_failures from spot_private.ops_jobs where operation=op)>=2 then rule_name:='job_failure';elsif n>=20 and fails>=5 and fails::numeric/n>=0.2 then rule_name:='error_spike';elsif streak=3 then rule_name:='three_failures';else return true;end if;
 insert into spot_private.ops_incidents(operation,source,rule)values(op,origin,rule_name)on conflict(operation,source)where state='open'do update set last_failure_at=stamp,occurrences=ops_incidents.occurrences+1;return true;
end$$;
create function public.ops_observe(operation text,request_id uuid,result text,error_class text default null,duration_ms integer default 0)returns boolean language sql security definer set search_path=''as $$select spot_private.ops_record(operation,request_id,result,error_class,duration_ms,'client')$$;
create function public.ops_record_server(operation text,request_id uuid,result text,error_class text default null,duration_ms integer default 0,job boolean default false)returns boolean language sql security definer set search_path=''as $$select spot_private.ops_record(operation,request_id,result,error_class,duration_ms,case when job then 'job'else 'edge'end)$$;
create function public.ops_purge(dry_run boolean default true)returns jsonb language plpgsql security definer set search_path=''as $$declare n bigint;m bigint;j bigint;begin
 if dry_run is null then raise exception 'OPS_INPUT';end if;perform pg_advisory_xact_lock(hashtextextended('soma-operational-recorder',53));
 select count(*)into n from spot_private.ops_events where created_at<=clock_timestamp()-interval '14 days';select count(*)into m from spot_private.ops_incidents where opened_at<=clock_timestamp()-interval '14 days';select count(*)into j from spot_private.ops_jobs where updated_at<=clock_timestamp()-interval '14 days';
 if not dry_run then delete from spot_private.ops_admission where created_at<=clock_timestamp()-interval '14 days';delete from spot_private.ops_events where id in(select id from spot_private.ops_events where created_at<=clock_timestamp()-interval '14 days'limit 1000);delete from spot_private.ops_incidents where id in(select id from spot_private.ops_incidents where opened_at<=clock_timestamp()-interval '14 days'limit 1000);delete from spot_private.ops_jobs where updated_at<=clock_timestamp()-interval '14 days';end if;
 return jsonb_build_object('dry_run',dry_run,'due_events',n,'due_incidents',m,'due_jobs',j);end$$;
create function public.ops_health()returns jsonb language plpgsql stable security definer set search_path=''as $$declare groups jsonb:='[]';g text;prefix text;off_state boolean;last_ok timestamptz;last_bad timestamptz;items jsonb;jobs jsonb;begin
 if spot_private.moderation_role()is distinct from 'ADMIN'then raise exception 'OPS_DENIED'using errcode='42501';end if;
 foreach g in array array['Auth','API/Edge','Storage/Photo','TRIBE/DD','ORA','SPOTTED','Match/Chat','Notifications','Analytics jobs','Moderation']loop
  prefix:=case g when 'Auth'then 'auth.'when 'Storage/Photo'then 'photo.'when 'TRIBE/DD'then 'dd.'when 'ORA'then 'ora.'when 'SPOTTED'then 'spotted.'when 'Match/Chat'then 'chat.'when 'Notifications'then 'notifications.'when 'Analytics jobs'then 'analytics.'when 'Moderation'then 'moderation.'else ''end;
  off_state:=case g when 'TRIBE/DD'then not(select discovery_enabled from spot_private.soma_v2_control)when 'Notifications'then not(select enabled from spot_private.notification_control)when 'Analytics jobs'then not(select enabled from spot_private.analytics_control)else false end;
  select max(created_at)filter(where result='success'),max(created_at)filter(where result='failure'and error_class in('dependency_error','timeout_error','internal_error'))into last_ok,last_bad from spot_private.ops_events where source<>'client'and operation like prefix||'%'and created_at>clock_timestamp()-interval '15 minutes';
  groups:=groups||jsonb_build_array(jsonb_build_object('name',g,'state',case when off_state then 'intentionally off'when last_bad is not null then 'degraded'else 'unknown'end,'last_success',last_ok,'last_failure',last_bad,'client_failure_reports',(select count(*)from spot_private.ops_events where source='client'and operation like prefix||'%'and result='failure'and created_at>clock_timestamp()-interval '15 minutes'),'coverage','partial; client reports unverified, no complete health proof'));
 end loop;
 select coalesce(jsonb_agg(to_jsonb(x)),'[]')into items from(select id,operation,source,rule,state,opened_at,last_failure_at,last_success_at,occurrences,email_state from spot_private.ops_incidents where opened_at>clock_timestamp()-interval '14 days'order by opened_at desc limit 100)x;
 select coalesce(jsonb_agg(to_jsonb(x)),'[]')into jobs from(select p.operation,j.last_success_at,j.last_failure_at,j.failure_class,j.last_duration_ms,j.consecutive_failures,p.expected_interval,case when p.expected_interval is not null then j.updated_at+p.expected_interval end next_expected_run,case when spot_private.ops_expected_off(p.operation)then 'intentionally off'when p.expected_interval is null then 'not configured'when j.updated_at is null then 'unknown'when j.consecutive_failures>0 or clock_timestamp()>j.updated_at+p.expected_interval*2 then 'degraded'when j.last_success_at is not null then 'healthy'else 'unknown'end state from spot_private.ops_job_policy p left join spot_private.ops_jobs j on j.operation=p.operation and j.updated_at>clock_timestamp()-interval '14 days')x;
 return jsonb_build_object('server_now',clock_timestamp(),'collection_enabled',(select enabled from spot_private.ops_control),'email_enabled',false,'email_state','not_configured','groups',groups,'incidents',items,'jobs',jobs,'retention_days',14,'analytics_dropped',(select dropped from spot_private.analytics_control),'dropped',(select dropped from spot_private.ops_control));end$$;
create function public.ops_recent(target_request uuid default null)returns jsonb language plpgsql stable security definer set search_path=''as $$declare data jsonb;begin
 if spot_private.moderation_role()is distinct from 'ADMIN'then raise exception 'OPS_DENIED'using errcode='42501';end if;
 select coalesce(jsonb_agg(to_jsonb(x)),'[]')into data from(select request_id,operation,source,result,error_class,duration_ms,created_at from spot_private.ops_events where created_at>clock_timestamp()-interval '14 days'and(target_request is null or request_id=target_request)order by created_at desc,id desc limit 100)x;return data;end$$;
revoke all on function spot_private.ops_expected_off(text),spot_private.ops_operation_valid(text),spot_private.ops_record(text,uuid,text,text,integer,text),public.ops_observe(text,uuid,text,text,integer),public.ops_record_server(text,uuid,text,text,integer,boolean),public.ops_purge(boolean),public.ops_health(),public.ops_recent(uuid)from public,anon,authenticated,service_role;
grant execute on function public.ops_observe(text,uuid,text,text,integer)to anon,authenticated;
grant execute on function public.ops_record_server(text,uuid,text,text,integer,boolean),public.ops_purge(boolean)to service_role;
grant execute on function public.ops_health(),public.ops_recent(uuid)to authenticated;
notify pgrst,'reload schema';commit;
